const rows = $input.all().map(i => i.json);
if (rows.length === 0) {
  return [];
}
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const rowsHtml = rows.map(r => `
  <tr>
    <td style="padding:8px;border:1px solid #ddd;font-weight:bold;">${esc(r.corp_name)}</td>
    <td style="padding:8px;border:1px solid #ddd;">${esc(String(r.priority_level).toUpperCase())} (${esc(r.priority_score)}점)</td>
    <td style="padding:8px;border:1px solid #ddd;white-space:pre-line;">${esc(r.change_summary)}</td>
  </tr>`).join('');
const html = `
  <h2>DeltaWatch 주간 변화 알림</h2>
  <table style="border-collapse:collapse;width:100%;">
    <tr>
      <th style="padding:8px;border:1px solid #ddd;text-align:left;">기업</th>
      <th style="padding:8px;border:1px solid #ddd;text-align:left;">우선순위</th>
      <th style="padding:8px;border:1px solid #ddd;text-align:left;">변화 내용</th>
    </tr>
    ${rowsHtml}
  </table>`;
return [{ json: { html, companyCount: rows.length } }];
